function exportReport(){const blob=new Blob([JSON.stringify(o.value,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`lan-im-admin-report-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(url)}
onMounted(load)
const common={textStyle:{color:'#8993a4'},tooltip:{trigger:'axis',backgroundColor:'#172033',borderWidth:0,textStyle:{color:'#fff'}},grid:{left:18,right:18,top:30,bottom:20,containLabel:true}}
