const typeOption=computed(()=>({tooltip:{trigger:'item'},legend:{bottom:0,textStyle:{color:'#8993a4'},itemWidth:8,itemHeight:8},series:[{type:'pie',radius:['56%','78%'],center:['50%','44%'],itemStyle:{borderColor:'var(--surface)',borderWidth:3,borderRadius:6},label:{show:false},data:o.value.message_types||[]}]}))
